function sphereDot(x, y, w, h, theta1, theta2){
	const viewAngle = acos(h/w)
	const radius = w/2

	push()
	translate(x, y)

	const pointX = cos(theta1)*radius*cos(theta2)
	const pointY = -radius*sin(theta2)*sin(viewAngle) + sin(theta1)*radius*cos(viewAngle)*cos(theta2)

	point(pointX,pointY)
	pop()
}

